    {
      "id": "c1",
      "start": 0.48,
      "end": 4.53,
      "text": "When the only server at Wok and Karahi in Spring walked out,",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c2",
      "start": 4.83,
      "end": 7.38,
      "text": "who was going to take the order?",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c3",
      "start": 8.04,
      "end": 10.59,
      "text": "The family didn't post a job ad.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c4",
      "start": 10.89,
      "end": 15.24,
      "text": "They put an AI host named Haniya at the front of the house.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c5",
      "start": 15.9,
      "end": 18.75,
      "text": "A guest scans a code at the table,",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c6",
      "start": 19.05,
      "end": 21.0,
      "text": "taps or talks to order,",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c7",
      "start": 21.3,
      "end": 23.25,
      "text": "and pays from a phone.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c8",
      "start": 23.91,
      "end": 27.06,
      "text": "Nothing is cooked until the order is paid for.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c9",
      "start": 28.22,
      "end": 32.27,
      "text": "The owner says the restaurant saves or wins back $9,650 a month,",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c10",
      "start": 32.57,
      "end": 34.52,
      "text": "and that's his own count.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c11",
      "start": 35.18,
      "end": 39.23,
      "text": "FOX 26 reports that kitchen staff now get all of the tips.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c12",
      "start": 39.89,
      "end": 42.44,
      "text": "When the employer takes no tip credit,",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c13",
      "start": 42.74,
      "end": 45.59,
      "text": "federal rules allow a tip pool with cooks.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c14",
      "start": 46.25,
      "end": 49.1,
      "text": "No report says whether this restaurant takes one.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c15",
      "start": 49.76,
      "end": 53.51,
      "text": "One customer said QR codes don't suit people like her mother.",
      "source": "authored_estimate",
      "start_measured": false,
      "end_measured": false
    },
    {
      "id": "c16",
      "start": 54.17,
      "end": 56.42,
      "text": "So software now takes the order,",
